import { describe, expect, it } from "vitest";
import cases from "./fixtures/grading_cases.json";
import { grade, netReturn, signalFor } from "./grading";
import type { Signal } from "./types";

// Fixture generated by ml/hopium/grading.py + ml/hopium/engine.py (see ml/tests/test_grading.py for the Python side).
describe("TypeScript grading == Python grading", () => {
  it(`agrees on all ${cases.length} generated cases`, () => {
    for (const c of cases) {
      const g = grade(c.signal as Signal, c.entry, c.exit);
      expect(g.outcome).toBe(c.outcome);
      expect(g.hit).toBe(c.hit);
      expect(g.move).toBeCloseTo(c.move, 12);
    }
  });
  it("live signal rule agrees with engine.py", () => {
    for (const c of cases) expect(signalFor(c.score, c.threshold)).toBe(c.live_signal);
  });
});

describe("grading edge cases", () => {
  it("UP +0.2% is a hit, +0.05% is flat, NO_CALL is sat out", () => {
    expect(grade("UP", 100, 100.2).outcome).toBe("HIT");
    expect(grade("UP", 100, 100.05).outcome).toBe("FLAT");
    expect(grade("NO_CALL", 100, 150).outcome).toBe("SAT_OUT");
    expect(grade("DOWN", 100, 99).outcome).toBe("HIT");
  });
  it("net return subtracts 0.2% round trip and shorts on DOWN", () => {
    expect(netReturn("UP", 0.01)).toBeCloseTo(0.008, 12);
    expect(netReturn("DOWN", 0.01)).toBeCloseTo(-0.012, 12);
    expect(netReturn("NO_CALL", 0.05)).toBe(0);
  });
});
